steps.solution:
function welcomeMessages(guests) {
  const messages = []
  for (let i = 0; i < guests.length; i++) {
    messages.push('Welcome, ' + guests[i] + '!')
  }
  return messages
}

console.log(welcomeMessages(['Ana', 'Ben']))
